"""Content-addressed domain reports with exact evidence and implementation inputs."""
from pathlib import Path
import os
import shutil
import uuid
from .model import validate_record
from .provenance import capture_code
from .util import atomic_json, canonical, digest, file_hash, now, read_json

PROJECT = Path(__file__).resolve().parents[1]


def publish_report(store, dataset, report, parameters, *, inputs=(), raw_inputs=(), records=(), entrypoint):
    inputs, raw_inputs = tuple(inputs), tuple(raw_inputs)
    code = capture_code(PROJECT, entrypoint)
    for ref in inputs:
        store.verify(ref)
    for ref in raw_inputs:
        store.artifact(ref)
    allowed = {canonical(ref) for ref in (*inputs, *raw_inputs)}
    canonical(report)
    with store.lock(dataset) as base:
        run_id = uuid.uuid4().hex
        staging = base/'processing'/run_id
        staging.mkdir()
        try:
            atomic_json(staging/'report.json', report)
            with (staging/'records.jsonl').open('wb') as stream:
                for record in records:
                    validate_record(record)
                    if any(canonical(item['input']) not in allowed for item in record['evidence']):
                        raise ValueError('Output evidence must reference a declared input')
                    stream.write(canonical(record)+b'\n')
            identity = {'schema_version':1,'dataset':dataset,
                        'definition':{'id':dataset,'kind':'derived','schema_version':1,'entrypoint':entrypoint},
                        'parameters':parameters,'inputs':list(inputs),'raw_inputs':list(raw_inputs),'code':code,
                        'outputs':{name:{'sha256':file_hash(staging/name),'bytes':(staging/name).stat().st_size}
                                   for name in ('report.json','records.jsonl')}}
            ref = {'dataset':dataset,'version':digest(identity)}
            atomic_json(staging/'manifest.json',{**identity,'version':ref['version']})
            for input_ref in inputs:
                store.verify(input_ref)
            for input_ref in raw_inputs:
                store.artifact(input_ref)
            if any(file_hash(PROJECT/name) != checksum for name,checksum in code['files'].items()):
                raise ValueError('Code changed during report publication')
            destination = store.version_dir(ref)
            if destination.exists():
                store.verify(ref)
            else:
                os.rename(staging,destination)
            atomic_json(base/'latest.json',ref)
            atomic_json(base/'runs'/f'{run_id}.json',{'run_id':run_id,'status':'succeeded','output':ref,'completed_at':now()})
            return ref
        except Exception as error:
            atomic_json(base/'runs'/f'{run_id}.json',{'run_id':run_id,'status':'failed','error':str(error),'completed_at':now()})
            raise
        finally:
            if staging.exists():
                shutil.rmtree(staging)


def load_report(store, ref):
    store.verify(ref)
    return read_json(store.version_dir(ref)/'report.json')

sources.worldmodel/banking.py:
"""Exact-cent commercial-bank ledger, separate from behavioral credit models.

Loans create deposits; settlement moves existing reserves. No reserve creation,
capital injection, interest, regulatory-capital rule, or central-bank reaction is
inferred. Equity may become negative and insolvency is explicitly retained.
"""
from copy import deepcopy
from decimal import Decimal, InvalidOperation


def _money(value, name, signed=False):
    if isinstance(value, bool) or not isinstance(value, (int, float, str, Decimal)):
        raise ValueError(f'{name} must be a finite monetary amount')
    try:
        amount = Decimal(str(value))
        if not amount.is_finite() or (not signed and amount < 0) or abs(amount) > Decimal('1000000000000'):
            raise ValueError(f'{name} must be finite and within the ledger range')
        cents = amount * 100
        if cents != cents.to_integral_value():
            raise ValueError(f'{name} must be an exact number of cents')
        return int(cents)
    except InvalidOperation as exc:
        raise ValueError(f'Invalid amount for {name}') from exc


def _name(value, field):
    if not isinstance(value, str) or not value:
        raise ValueError(f'{field} must be a nonempty identifier')
    return value


def _units(cents):
    return cents / 100


def _status(bank):
    return 'insolvent' if bank['equity'] < 0 else 'zero_equity' if bank['equity'] == 0 else 'solvent'


def _check(banks, initial_reserves):
    for bank in banks.values():
        if any(abs(v) > 100000000000000 for v in (bank['reserves'], bank['equity'], *bank['loans'].values(), *bank['accounts'].values())):
            raise ValueError('Balance exceeds bounded ledger range')
        if bank['reserves'] < 0 or any(v < 0 for v in (*bank['loans'].values(), *bank['accounts'].values())):
            raise ValueError('Negative reserve, principal or deposit balance')
        if bank['reserves'] + sum(bank['loans'].values()) != sum(bank['accounts'].values()) + bank['equity']:
            raise ValueError(f"Bank {bank['id']} fails assets = deposits + equity")
    if sum(b['reserves'] for b in banks.values()) != initial_reserves:
        raise ValueError('Aggregate reserves were not conserved')


def _export(banks):
    return [{'id': b['id'], 'reserves': _units(b['reserves']), 'equity': _units(b['equity']),
             'loans': {k: _units(v) for k, v in b['loans'].items()},
             'accounts': {k: _units(v) for k, v in b['accounts'].items()}, 'status': _status(b)} for b in banks.values()]


def simulate_banking(config):
    """Apply a bounded transaction sequence atomically to a copied opening state.

    Config banks require id,reserves,loans:{borrower:principal},equity,accounts.
    Loan transactions use bank,borrower,amount. Transfers use bank,from_account,
    to_bank,to_account,amount. New destination accounts start at zero. All amounts
    use one USD denomination, exact cents. Signed equity preserves insolvency;
    negative reserves, loans, deposits and transaction amounts are prohibited.
    A failure raises without changing caller inputs or publishing partial state.
    """
    if not isinstance(config, dict) or set(config) - {'banks', 'transactions', 'currency'}:
        raise ValueError('Unknown banking config fields')
    if config.get('currency', 'USD') != 'USD':
        raise ValueError('This ledger currently supports USD cents only')
    supplied = config.get('banks')
    transactions = config.get('transactions', [])
    if not isinstance(supplied, list) or not 1 <= len(supplied) <= 100:
        raise ValueError('banks must contain 1 to 100 banks')
    if not isinstance(transactions, list) or len(transactions) > 10000:
        raise ValueError('transactions must be a list of at most 10000 entries')
    banks = {}
    for item in supplied:
        if not isinstance(item, dict) or set(item) - {'id', 'reserves', 'loans', 'equity', 'accounts', 'status'}:
            raise ValueError('Unknown bank fields')
        if not {'id', 'reserves', 'loans', 'equity', 'accounts'} <= set(item):
            raise ValueError('Bank requires id, reserves, loans, equity and accounts')
        bank_id = _name(item.get('id'), 'bank.id')
        if bank_id in banks:
            raise ValueError('Duplicate bank ID')
        bank = {'id': bank_id, 'reserves': _money(item['reserves'], 'reserves'), 'equity': _money(item['equity'], 'equity', signed=True)}
        for field in ('loans', 'accounts'):
            if not isinstance(item[field], dict):
                raise ValueError(f'{field} must map owner IDs to balances')
            bank[field] = {_name(k, field): _money(v, field) for k, v in item[field].items()}
        if 'status' in item and item['status'] != _status(bank):
            raise ValueError('Supplied bank status conflicts with equity')
        banks[bank_id] = bank
    # Bound state × transactions, since audit retains complete before/after state.
    state_cells = sum(3 + len(b['accounts']) + len(b['loans']) for b in banks.values())
    if (len(transactions) + 1) * (state_cells + 2 * len(transactions)) > 1000000:
        raise ValueError('Banking audit state budget exceeded (1000000 balance cells)')
    reserves = sum(b['reserves'] for b in banks.values())
    initial_deposits = sum(sum(b['accounts'].values()) for b in banks.values())
    initial_loans = sum(sum(b['loans'].values()) for b in banks.values())
    _check(banks, reserves)
    snapshots = [{'step': 0, 'banks': _export(banks)}]
    journal, audit, events = [], [], []
    for step, transaction in enumerate(transactions, 1):
        if not isinstance(transaction, dict):
            raise ValueError('Transaction must be an object')
        kind = transaction.get('kind')
        fields = {'kind', 'bank', 'amount', 'borrower'} if kind in ('originate', 'repay', 'default') else {'kind', 'bank', 'amount', 'from_account', 'to_bank', 'to_account'} if kind == 'transfer' else None
        if fields is None or set(transaction) != fields:
            raise ValueError('Unknown transaction kind or missing/unknown transaction fields')
        bank_id = _name(transaction['bank'], 'bank')
        if bank_id not in banks:
            raise ValueError('Unknown bank')
        bank = banks[bank_id]
        amount = _money(transaction['amount'], 'amount')
        if amount <= 0:
            raise ValueError('Transaction amount must be positive')
        before = _export(banks)
        statuses = {k: _status(v) for k, v in banks.items()}
        postings = []
        totals = {}

        def posting(bid, account, debit=0, credit=0):
            totals[bid] = totals.get(bid, 0) + debit - credit
            postings.append({'bank': bid, 'account': account, 'debit': _units(debit), 'credit': _units(credit)})

        if kind in ('originate', 'repay', 'default'):
            borrower = _name(transaction['borrower'], 'borrower')
            loan = bank['loans'].get(borrower, 0)
            deposit = bank['accounts'].get(borrower, 0)
            if kind == 'originate':
                if bank['equity'] <= 0:
                    raise ValueError('Origination prohibited for a bank with nonpositive equity')
                bank['loans'][borrower] = loan + amount
                bank['accounts'][borrower] = deposit + amount
                posting(bank_id, 'loans:' + borrower, debit=amount)
                posting(bank_id, 'deposits:' + borrower, credit=amount)
            else:
                if amount > loan:
                    raise ValueError('Repayment/default exceeds outstanding borrower principal')
                if kind == 'repay':
                    if amount > deposit:
                        raise ValueError('Insufficient borrower deposit for repayment')
                    bank['accounts'][borrower] = deposit - amount
                    posting(bank_id, 'deposits:' + borrower, debit=amount)
                else:
                    bank['equity'] -= amount
                    posting(bank_id, 'equity', debit=amount)
                    events.append({'kind': 'loan_written_off', 'step': step, 'bank': bank_id, 'borrower': borrower, 'amount': _units(amount)})
                bank['loans'][borrower] = loan - amount
                posting(bank_id, 'loans:' + borrower, credit=amount)
        else:
            source = _name(transaction['from_account'], 'from_account')
            target = _name(transaction['to_account'], 'to_account')
            target_bank_id = _name(transaction['to_bank'], 'to_bank')
            if target_bank_id not in banks:
                raise ValueError('Unknown receiving bank')
            receiving = banks[target_bank_id]
            if source not in bank['accounts'] or bank['accounts'][source] < amount:
                raise ValueError('Insufficient sender deposit')
            if bank_id != target_bank_id and bank['reserves'] < amount:
                raise ValueError('Insufficient reserves for interbank settlement')
            bank['accounts'][source] -= amount
            receiving['accounts'][target] = receiving['accounts'].get(target, 0) + amount
            posting(bank_id, 'deposits:' + source, debit=amount)
            if bank_id != target_bank_id:
                bank['reserves'] -= amount
                receiving['reserves'] += amount
                posting(bank_id, 'reserves', credit=amount)
                posting(target_bank_id, 'reserves', debit=amount)
            posting(target_bank_id, 'deposits:' + target, credit=amount)
        _check(banks, reserves)
        if any(totals.values()):
            raise ValueError('Transaction journal does not balance per bank')
        for bid, state in banks.items():
            if _status(state) == 'insolvent' and statuses[bid] != 'insolvent':
                events.append({'kind': 'bank_insolvent', 'step': step, 'bank': bid, 'equity': _units(state['equity']), 'bailout': False})
        after = _export(banks)
        journal.append({'step': step, 'kind': kind, 'postings': postings, 'balanced': True})
        audit.append({'step': step, 'transaction': deepcopy(transaction), 'before': before, 'after': after})
        snapshots.append({'step': step, 'banks': after})
    return {'banks': _export(banks), 'currency': 'USD', 'snapshots': snapshots, 'journal': journal, 'audit': audit, 'events': events,
            'accounting': {'balanced': True, 'precision': 'integer cents', 'reserve_change': 0,
                          'initial_reserves': _units(reserves), 'final_reserves': _units(reserves),
                          'deposit_change': _units(sum(sum(b['accounts'].values()) for b in banks.values()) - initial_deposits),
                          'loan_change': _units(sum(sum(b['loans'].values()) for b in banks.values()) - initial_loans)},
            'epistemic_status': 'synthetic_scenario', 'calibration_status': 'accounting identities only; no behavioral calibration',
            'assumptions': ['Commercial loan origination creates deposits; repayment extinguishes both.',
                            'Fixed aggregate reserves; no central-bank lending, reserve interest or bailout.',
                            'No interest, capital adequacy, liquidity regulation, collateral recovery or borrower credit model.',
                            'Default is an explicit full principal write-off amount; deposits are not erased.',
                            'Equity may be negative; insolvent banks cannot originate but can settle funded transfers and repayments.']}


def _predict(inputs, parameters, context):
    if context['dt_seconds'] != 86400:
        raise ValueError('Banking ledger requires exactly one daily cadence')
    result = simulate_banking(inputs['banking_state']['value'])
    state = {'banks': result['banks'], 'currency': result['currency'], 'transactions': []}
    return {'pressures': [{'port': 'banking_state', 'mode': 'set', 'value': state, 'unit': None, 'strength': 1, 'confidence': 1}],
            'events': result['events'], 'diagnostics': {'accounting': result['accounting'], 'journal': result['journal'],
                                                     'epistemic_status': 'synthetic_scenario', 'calibrated': False}}


def register_banking_processes(registry):
    port = {'type': 'object', 'unit': None}
    registry.register_process({'id': 'banking_ledger', 'inputs': {'banking_state': port}, 'outputs': {'banking_state': port},
        'topology': 'Explicit banks, depositor accounts and borrower principal balances.',
        'description': 'Apply a supplied daily transaction batch; accounting mechanism, no behavioral prediction.', 'illustrative': True, 'validated': False})
    registry.register_implementation({'id': 'banking_ledger.deterministic', 'process_id': 'banking_ledger', 'fidelity': 'deterministic',
        'min_step_seconds': 86400, 'max_step_seconds': 86400, 'cost_per_call': 1, 'output_timing': 'end_of_step',
        'description': 'Exact-cent balanced transaction batch; clears executed transactions.'}, _predict)
    return registry


def schema():
    return {'entity_types': {'bank': {'parent': 'business'}, 'central_bank': {'parent': 'government_agency'},
                             'financial_asset': {'parent': 'asset'}, 'loan': {'parent': 'financial_asset'}, 'deposit_account': {'parent': 'account'}},
            'relations': {'account_at_bank': {'domain': 'deposit_account', 'range': 'bank'},
                          'loan_issued_by': {'domain': 'loan', 'range': 'bank'},
                          'has_deposit_account': {'domain': 'agent', 'range': 'deposit_account'},
                          'borrows_loan': {'domain': 'agent', 'range': 'loan'}},
            'variables': {name: {'type': 'number', 'unit': 'USD', 'domain': domain} for name, domain in [
                ('bank_reserves', 'bank'), ('bank_equity', 'bank'), ('bank_deposits', 'bank'),
                ('loan_principal', 'loan'), ('deposit_balance', 'deposit_account')]}}

sources.worldmodel/catalog.py:
"""Version-controlled dataset declarations and dependency planning."""
from pathlib import Path
from .util import read_json, slug


class Catalog:
    def __init__(self, root):
        self.root = Path(root)

    def get(self, dataset):
        slug(dataset)
        path = self.root / dataset / 'dataset.json'
        if not path.is_file():
            raise ValueError(f'Unknown dataset: {dataset}')
        definition = read_json(path)
        if definition.get('id') != dataset or definition.get('schema_version') != 1:
            raise ValueError(f'Invalid dataset definition: {dataset}')
        if definition.get('kind') not in ('source', 'derived'):
            raise ValueError(f'Invalid dataset kind: {dataset}')
        dependencies = definition.get('dependencies', [])
        if not isinstance(dependencies, list) or len(dependencies) != len(set(dependencies)):
            raise ValueError(f'Invalid dependencies: {dataset}')
        for dependency in dependencies:
            slug(dependency)
        return definition

    def list(self):
        return [self.get(path.parent.name) for path in sorted(self.root.glob('*/dataset.json'))]

    def plan(self, target):
        order, active, visited = [], set(), set()

        def visit(dataset):
            if dataset in active:
                raise ValueError(f'Dependency cycle at {dataset}')
            if dataset in visited:
                return
            definition = self.get(dataset)
            active.add(dataset)
            for dependency in definition.get('dependencies', []):
                visit(dependency)
            active.remove(dataset)
            visited.add(dataset)
            order.append(dataset)

        visit(target)
        return order

sources.worldmodel/cli.py:
"""Offline-first command line interface; JSON output is scriptable."""
import argparse
import json
import os
from pathlib import Path
import sys
from .catalog import Catalog
from .fetch import fetch
from .graph import Graph
from .pipeline import Runner
from .store import Store
from .util import atomic_json, slug, read_json

PROJECT = Path(__file__).resolve().parents[1]


def reference(value, store):
    if '@' in value:
        dataset, version = value.split('@', 1)
        return {'dataset': dataset, 'version': version}
    return store.latest(value)


def parser():
    p = argparse.ArgumentParser(prog='wm', description='Versioned evidence datasets and temporal graph')
    p.add_argument('--data-root', type=Path, default=Path(os.environ.get('WORLD_MODEL_DATA', PROJECT / 'data')))
    p.add_argument('--catalog-root', type=Path, default=PROJECT / 'data')
    sub = p.add_subparsers(dest='command', required=True)
    from .strategic_cli import add_commands
    add_commands(sub)
    sub.add_parser('catalog', help='List declarations and readiness')
    sub.add_parser('ontology', help='Describe typed entities, relations and variables')
    sub.add_parser('processes', help='Describe process contracts and registered implementations')
    sub.add_parser('unify', help='Normalize existing real samples and build a verified typed graph offline')
    mat = sub.add_parser('materialize', help='Publish a requested temporal view or explicit forecast scenario')
    mat.add_argument('reference')
    mat.add_argument('--request', type=Path, required=True)
    view = sub.add_parser('view', help='Read a verified materialized view and execution trace')
    view.add_argument('reference')
    sub.add_parser('init', help='Create runtime directories for catalog entries')
    new = sub.add_parser('new', help='Create a source or derived dataset declaration')
    new.add_argument('dataset')
    new.add_argument('--kind', choices=['source', 'derived'], required=True)
    new.add_argument('--entrypoint', required=True)
    new.add_argument('--depends-on', action='append', default=[])
    new.add_argument('--description', required=True)
    imp = sub.add_parser('import', help='Snapshot a local file into immutable raw storage')
    imp.add_argument('dataset')
    imp.add_argument('path', type=Path)
    imp.add_argument('--source-json', default='{}', help='Publisher, release, license, URL, etc.')
    download = sub.add_parser('fetch', help='Explicit download; never called automatically by run')
    download.add_argument('dataset')
    download.add_argument('url')
    download.add_argument('--allow-network', action='store_true')
    download.add_argument('--sha256')
    download.add_argument('--max-bytes', type=int, help='May lower the configured download budget')
    download.add_argument('--source-json', default='{}')
    download.add_argument('--user-agent', help='Publisher-required contact identity')
    plan = sub.add_parser('plan')
    plan.add_argument('dataset')
    run = sub.add_parser('run')
    run.add_argument('dataset')
    run.add_argument('--parameters', default='{}', help='JSON object; target only')
    run.add_argument('--input', action='append', default=[], help='Pin dependency dataset@version')
    run.add_argument('--raw', action='append', default=[], help='Pin source dataset@artifact; repeat for shards')
    for name in ('inspect', 'lineage', 'verify'):
        command = sub.add_parser(name)
        command.add_argument('reference', help='dataset or dataset@version')
    sample = sub.add_parser('sample', help='Fetch bounded exploratory samples without changing full-data pointers')
    sample.add_argument('dataset', help='Dataset ID or all')
    sample.add_argument('--allow-network', action='store_true')
    explore = sub.add_parser('explore', help='Inspect a verified sample profile')
    explore.add_argument('dataset')
    sub.add_parser('demo', help='Import tiny fictional fixtures and run the full pipeline offline')
    build = sub.add_parser('graph-build')
    build.add_argument('references', nargs='+')
    build.add_argument('--index', type=Path)
    for name, argument in [('neighbors', 'entity'), ('observations', 'metric')]:
        command = sub.add_parser(name)
        command.add_argument(argument)
        command.add_argument('--index', type=Path)
        command.add_argument('--valid-at')
        command.add_argument('--known-at')
        command.add_argument('--limit', type=int, default=100)
        if name == 'neighbors':
            command.add_argument('--hops', type=int, default=1)
    return p


def object_json(value):
    result = json.loads(value)
    if not isinstance(result, dict):
        raise ValueError('Expected a JSON object')
    return result


def execute(args):
    catalog, store = Catalog(args.catalog_root), Store(args.data_root)
    runner = Runner(catalog, store, PROJECT)
    command = args.command
    from .strategic_cli import COMMANDS, execute as strategic_execute
    if command in COMMANDS:
        return strategic_execute(args, catalog, store, PROJECT, reference)
    if command == 'ontology':
        from .ontology import describe
        return describe()
    if command == 'processes':
        from .process_library import default_registry
        return default_registry().describe()
    if command == 'unify':
        from .unify import unify
        return unify(catalog, store, PROJECT)
    if command in ('materialize', 'view'):
        from .materialize import materialize, load_view
        ref = reference(args.reference, store)
        if command == 'view':
            return load_view(store, ref)
        result = materialize(store, ref, read_json(args.request))
        return {key: result[key] for key in ('artifact', 'plan', 'execution', 'limitations')}
    if command == 'sample':
        from .sampling import sample_dataset
        definitions = catalog.list() if args.dataset == 'all' else [catalog.get(args.dataset)]
        results = []
        for definition in definitions:
            result = sample_dataset(store, definition, allow_network=args.allow_network)
            results.append(result)
            print(f'{definition["id"]}: {result["status"]}', file=sys.stderr, flush=True)
        return results
    if command == 'explore':
        from .sampling import explore
        return explore(store, args.dataset)
    if command == 'catalog':
        return [{k: d.get(k) for k in ('id', 'kind', 'status', 'description', 'dependencies')}
                for d in catalog.list()]
    if command == 'init':
        names = [d['id'] for d in catalog.list()]
        for name in names:
            store.initialize(name)
        return {'data_root': str(store.root), 'datasets': names}
    if command == 'new':
        slug(args.dataset)
        for dependency in args.depends_on:
            catalog.get(dependency)
        path = catalog.root / args.dataset / 'dataset.json'
        if path.exists():
            raise ValueError('Dataset already exists')
        definition = {'id': args.dataset, 'schema_version': 1, 'kind': args.kind,
                      'description': args.description, 'status': 'configured',
                      'entrypoint': args.entrypoint, 'dependencies': args.depends_on, 'parameters': {},
                      'sampling': {'strategy': 'derived' if args.kind == 'derived' else 'blocked',
                                   'format': 'jsonl', 'max_rows': 100, 'max_sample_bytes': 1024 ** 2,
                                   'max_download_bytes': 1024 ** 2, 'max_uncompressed_bytes': 1024 ** 2,
                                   'disk_budget_bytes': 64 * 1024 ** 2,
                                   'criteria': 'First 100 records, at most 1 MiB',
                                   'reason': 'Configure a sampling URL and source-specific format'}}
        atomic_json(path, definition)
        store.initialize(args.dataset)
        return definition
    if command in ('import', 'fetch'):
        definition = catalog.get(args.dataset)
        if definition['kind'] != 'source':
            raise ValueError('Raw acquisition belongs to source datasets')
        metadata = {**definition.get('source', {}), **object_json(args.source_json)}
        if command == 'import':
            return store.import_file(args.dataset, args.path, metadata)
        headers = {'User-Agent': args.user_agent} if args.user_agent else None
        budget = definition.get('sampling', {}).get('max_download_bytes', 1024 ** 2)
        if args.max_bytes is not None:
            budget = min(budget, args.max_bytes)
        return fetch(store, args.dataset, args.url, metadata, allow_network=args.allow_network,
                     expected_sha256=args.sha256, max_bytes=budget, headers=headers)
    if command == 'plan':
        return [{'dataset': name, 'status': catalog.get(name).get('status'),
                 'entrypoint': catalog.get(name).get('entrypoint')} for name in catalog.plan(args.dataset)]
    if command == 'run':
        inputs, raws = {}, {}
        for value in args.input:
            if '@' not in value:
                raise ValueError('--input requires dataset@version')
            ref = reference(value, store)
            if ref['dataset'] in inputs:
                raise ValueError('Duplicate input pin')
            inputs[ref['dataset']] = ref
        for value in args.raw:
            if '@' not in value:
                raise ValueError('--raw requires dataset@artifact')
            dataset, artifact = value.split('@', 1)
            raws.setdefault(dataset, []).append({'dataset': dataset, 'artifact': artifact})
        return runner.run(args.dataset, parameters=object_json(args.parameters), raw_refs=raws, input_refs=inputs)
    if command in ('inspect', 'lineage', 'verify'):
        ref = reference(args.reference, store)
        if command == 'inspect':
            return store.manifest(ref)
        if command == 'lineage':
            return store.lineage(ref)
        return {'reference': ref, 'verified': store.verify(ref)}
    default_index = store.root / 'world_evidence/index.sqlite'
    if (store.root/'strategic_evidence/index.sqlite').exists():
        default_index = store.root/'strategic_evidence/index.sqlite'
    if command == 'demo' or not default_index.exists():
        default_index = store.root / 'world_graph/index.sqlite'
    graph = Graph(getattr(args, 'index', None) or default_index)
    if command == 'demo':
        for dataset, filename in [('demo_countries', 'countries.csv'), ('demo_graph', 'graph.jsonl')]:
            store.import_file(dataset, PROJECT / 'tests/fixtures' / filename,
                              catalog.get(dataset)['source'])
        ref = runner.run('world_graph')
        return {'output': ref, 'graph': graph.build(store, [ref]), 'fictional_data': True}
    if command == 'graph-build':
        return graph.build(store, [reference(value, store) for value in args.references])
    filters = {'limit': args.limit, 'valid_at': args.valid_at, 'known_at': args.known_at}
    if command == 'neighbors':
        return graph.neighbors(args.entity, hops=args.hops, **filters)
    return graph.observations(args.metric, **filters)


def main(argv=None):
    args = parser().parse_args(argv)
    try:
        result = execute(args)
        print(json.dumps(result, indent=2, ensure_ascii=False, allow_nan=False))
        return 0
    except (ValueError, OSError, RuntimeError, KeyError, TypeError, AttributeError) as error:
        print(json.dumps({'error': str(error)}), file=sys.stderr)
        return 1

sources.worldmodel/economy.py:
"""Bounded, closed-cash daily economy. Behavioral coefficients are assumptions.

USD cash moves between a bank, firms, supplier and explicit customer sector.
This is a cash-funded lender, not a commercial-bank deposit creation model.
Inventory uses weighted-average acquisition cost; loans are floating rate.
"""
from copy import deepcopy
import math


def _number(value, name, minimum=0):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < minimum:
        raise ValueError(f'{name} must be finite and >= {minimum}')
    return float(value)


def example_economy():
    return {'days': 30, 'energy_price': 10, 'bank': {'cash': 10000, 'annual_rate': .05, 'credit_limit': 10000},
            'supplier': {'cash': 1000}, 'customers': {'cash': 100000},
            'businesses': [{'id': 'factory', 'cash': 1000, 'loan': 0, 'inventory': 20,
                'storage_capacity': 200, 'credit_limit': 2000, 'daily_energy_need': 10,
                'revenue_per_unit': 16, 'policy': {'target_days': 3, 'anticipation': 2,
                                                 'expected_price_change': .25}}],
            'shocks': [{'step': 10, 'energy_price': 14, 'annual_rate': .08}]}


def _prepare(config):
    config = deepcopy(config)
    days = config.get('days', 30)
    if isinstance(days, bool) or not isinstance(days, int) or not 0 <= days <= 10000:
        raise ValueError('days must be an integer in 0..10000')
    price = _number(config['energy_price'], 'energy_price')
    if price == 0:
        raise ValueError('energy_price must be positive')
    bank = {key: _number(config['bank'][key], f'bank.{key}') for key in ('cash', 'annual_rate', 'credit_limit')}
    supplier = {'cash': _number(config['supplier']['cash'], 'supplier.cash')}
    customers = {'cash': _number(config.get('customers', {'cash': 100000})['cash'], 'customers.cash')}
    businesses = config['businesses']
    if not isinstance(businesses, list) or not 1 <= len(businesses) <= 1000 or days * len(businesses) > 100000:
        raise ValueError('businesses and days exceed bounded simulation work budget')
    ids = set()
    for firm in businesses:
        ident = firm['id']
        if not isinstance(ident, str) or not ident or ':' in ident or ident in ids or ident in {'bank', 'supplier', 'customers'}:
            raise ValueError('Business IDs must be distinct nonreserved strings without colons')
        ids.add(ident)
        for key in ('cash', 'loan', 'inventory', 'storage_capacity', 'credit_limit', 'daily_energy_need', 'revenue_per_unit'):
            firm[key] = _number(firm[key], f'{ident}.{key}')
        if firm['loan'] > firm['credit_limit'] or firm['inventory'] > firm['storage_capacity']:
            raise ValueError('Initial credit or storage limit exceeded')
        policy = firm.setdefault('policy', {})
        for key, default in [('target_days', 1), ('anticipation', 0), ('expected_price_change', 0)]:
            policy[key] = _number(policy.get(key, default), f'{ident}.policy.{key}', -1 if key == 'expected_price_change' else 0)
        firm.update(inventory_value=firm['inventory'] * price, defaulted=False, output=0., profit=0., interest=0., energy_spend=0.)
    bank['loans'] = sum(f['loan'] for f in businesses)
    if bank['loans'] > bank['credit_limit']:
        raise ValueError('Initial aggregate bank credit limit exceeded')
    bank.update(equity=bank['cash'] + bank['loans'], interest_income=0., credit_losses=0.)
    shocks = config.get('shocks', [])
    seen = set()
    for shock in shocks:
        step = shock['step']
        if isinstance(step, bool) or not isinstance(step, int) or step < 1 or step in seen:
            raise ValueError('Shock steps must be unique positive integers')
        if set(shock) - {'step', 'energy_price', 'annual_rate'}:
            raise ValueError('Unknown shock field')
        seen.add(step)
        for field in ('energy_price', 'annual_rate'):
            if field in shock:
                _number(shock[field], field)
                if field == 'energy_price' and shock[field] == 0:
                    raise ValueError('energy_price must be positive')
    return days, price, bank, supplier, customers, businesses, {s['step']: s for s in shocks}


def simulate_economy(config):
    """Return daily snapshots, balanced debit/credit journal, events and metrics.

    Each day: apply shocks, pay interest/default, fund and purchase inventories,
    consume energy and sell output. Firm order is explicit credit priority.
    No future shock is observed by purchasing policy: expectations are inputs.
    """
    days, price, bank, supplier, customers, firms, shocks = _prepare(config)
    journal, events, snapshots, ledger = [], [], [], {}

    def post(step, kind, *entries):
        postings = [{'account': account, 'debit': max(amount, 0.), 'credit': max(-amount, 0.)}
                    for account, amount in entries if amount != 0]
        if abs(sum(e['debit'] - e['credit'] for e in postings)) > 1e-7:
            raise ValueError('Unbalanced transaction')
        for e in postings:
            ledger[e['account']] = ledger.get(e['account'], 0.) + e['debit'] - e['credit']
        journal.append({'step': step, 'kind': kind, 'postings': postings})

    post(0, 'opening_bank', ('bank:cash', bank['cash']), ('bank:loans', bank['loans']), ('bank:equity', -bank['equity']))
    for name, actor in [('supplier', supplier), ('customers', customers)]:
        post(0, 'opening_' + name, (name + ':cash', actor['cash']), (name + ':equity', -actor['cash']))
    for f in firms:
        ident = f['id']
        post(0, 'opening_business', (ident + ':cash', f['cash']), (ident + ':inventory', f['inventory_value']),
             (ident + ':loan', -f['loan']), (ident + ':equity', -(f['cash'] + f['inventory_value'] - f['loan'])))

    def snapshot(step):
        bank['equity'] = bank['cash'] + bank['loans']
        for firm in firms:
            firm['equity'] = firm['cash'] + firm['inventory_value'] - firm['loan']
            if firm['equity'] < -1e-9 and not any(e['kind'] == 'insolvency' and e['business'] == firm['id'] for e in events):
                events.append({'step': step, 'kind': 'insolvency', 'business': firm['id'], 'equity': firm['equity'],
                               'recognition': 'Negative book equity; continues operating while daily interest can be paid.'})
        metrics = {'total_cash': bank['cash'] + supplier['cash'] + customers['cash'] + sum(f['cash'] for f in firms),
            'total_loans': bank['loans'], 'total_inventory': sum(f['inventory'] for f in firms),
            'total_output': sum(f['output'] for f in firms), 'total_profit': sum(f['profit'] for f in firms),
            'total_interest': sum(f['interest'] for f in firms), 'total_energy_spend': sum(f['energy_spend'] for f in firms),
            'defaults': sum(f['defaulted'] for f in firms), 'stockouts': sum(e['kind'] == 'stockout' for e in events),
            'bank_equity': bank['equity'], 'business_cash': sum(f['cash'] for f in firms),
            'insolvent_businesses': sum(f['equity'] < -1e-9 for f in firms)}
        snapshots.append(deepcopy({'step': step, 'energy_price': price, 'annual_rate': bank['annual_rate'],
            'metrics': metrics, 'businesses': firms, 'bank': bank, 'supplier': supplier, 'customers': customers}))

    snapshot(0)
    for step in range(1, days + 1):
        if step in shocks:
            shock = shocks[step]
            price = shock.get('energy_price', price)
            bank['annual_rate'] = shock.get('annual_rate', bank['annual_rate'])
            events.append(dict(shock, kind='shock'))
        for firm in firms:
            if firm['defaulted']:
                continue
            ident = firm['id']
            due = firm['loan'] * bank['annual_rate'] / 365
            paid = min(due, firm['cash'])
            if paid:
                firm['cash'] -= paid
                bank['cash'] += paid
                bank['interest_income'] += paid
                firm['interest'] += paid
                firm['profit'] -= paid
                post(step, 'interest', (ident + ':interest_expense', paid), (ident + ':cash', -paid),
                     ('bank:cash', paid), ('bank:interest_revenue', -paid))
            if due - paid > 1e-9:
                loss = firm['loan']
                bank['loans'] -= loss
                bank['credit_losses'] += loss
                firm['loan'] = 0.
                firm['defaulted'] = True
                post(step, 'default', ('bank:credit_loss', loss), ('bank:loans', -loss),
                     (ident + ':loan', loss), (ident + ':debt_relief', -loss))
                events.append({'step': step, 'kind': 'default', 'business': ident, 'principal_written_off': loss,
                               'unpaid_interest': due - paid})
                continue
            policy = firm['policy']
            # Carrying cost uses the declared target horizon; expectations never inspect shocks.
            incentive = max(0., policy['expected_price_change'] - bank['annual_rate'] * policy['target_days'] / 365)
            target = min(firm['storage_capacity'], firm['daily_energy_need'] * policy['target_days'] *
                         (1 + policy['anticipation'] * incentive))
            desired_cost = max(0., target - firm['inventory']) * price
            borrowed = min(max(0., desired_cost - firm['cash']), bank['cash'],
                           max(0., bank['credit_limit'] - bank['loans']), max(0., firm['credit_limit'] - firm['loan']))
            if borrowed:
                bank['cash'] -= borrowed
                bank['loans'] += borrowed
                firm['cash'] += borrowed
                firm['loan'] += borrowed
                post(step, 'loan_origination', ('bank:loans', borrowed), ('bank:cash', -borrowed),
                     (ident + ':cash', borrowed), (ident + ':loan', -borrowed))
            spent = min(desired_cost, firm['cash'])
            purchased = spent / price
            if spent:
                firm['cash'] -= spent
                supplier['cash'] += spent
                firm['inventory'] += purchased
                firm['inventory_value'] += spent
                firm['energy_spend'] += spent
                post(step, 'energy_purchase', (ident + ':inventory', spent), (ident + ':cash', -spent),
                     ('supplier:cash', spent), ('supplier:revenue', -spent))
            if firm['inventory'] + 1e-9 < firm['daily_energy_need']:
                events.append({'step': step, 'kind': 'stockout', 'business': ident,
                               'unmet_energy': firm['daily_energy_need'] - firm['inventory']})
            output = min(firm['daily_energy_need'], firm['inventory'])
            if firm['revenue_per_unit']:
                output = min(output, customers['cash'] / firm['revenue_per_unit'])
            cost = output * (firm['inventory_value'] / firm['inventory'] if firm['inventory'] else 0.)
            revenue = output * firm['revenue_per_unit']
            firm['inventory'] = max(0., firm['inventory'] - output)
            firm['inventory_value'] = max(0., firm['inventory_value'] - cost)
            firm['cash'] += revenue
            customers['cash'] = max(0., customers['cash'] - revenue)
            firm['output'] += output
            firm['profit'] += revenue - cost
            if output:
                post(step, 'production_sale', (ident + ':cost_of_goods', cost), (ident + ':inventory', -cost),
                     (ident + ':cash', revenue), (ident + ':sales_revenue', -revenue),
                     ('customers:consumption_expense', revenue), ('customers:cash', -revenue))
        snapshot(step)
    result = {'snapshots': snapshots, 'journal': journal, 'ledger': ledger, 'events': events,
              'metrics': deepcopy(snapshots[-1]['metrics']), 'status': {'synthetic': True, 'calibrated': False},
              'assumptions': ['USD amounts; energy quantity is a consistent user-chosen unit; one output per energy unit.',
                  'Cash-funded lender; no deposit creation, reserves, interbank market or central bank balance sheet.',
                  'Floating annual loan rate / 365; unpaid daily interest triggers immediate default and full principal writeoff.',
                  'No loan maturity or principal repayment; defaults halt production, with no collateral recovery. Operating profit excludes default debt relief.',
                  'Supplier has unlimited energy at exogenous price; customers have finite cash.',
                  'Business list order is priority for scarce bank cash and customer cash.',
                  'Inventory target = daily need * target days * (1 + anticipation * max(expected price change - annual rate * target days / 365, 0)), capped by storage.',
                  'Behavioral coefficients are illustrative inputs, not calibrated responses; future shocks are not read by firms.']}
    result['accounting'] = validate_accounting(result)
    return result


def validate_accounting(result, tolerance=1e-7):
    """Recompute ledger and verify journals, cash conservation and loan symmetry."""
    ledger = {}
    for entry in result['journal']:
        total = 0.
        for p in entry['postings']:
            debit, credit = _number(p['debit'], 'debit'), _number(p['credit'], 'credit')
            if debit and credit:
                raise ValueError('Posting cannot debit and credit simultaneously')
            total += debit - credit
            ledger[p['account']] = ledger.get(p['account'], 0.) + debit - credit
        if abs(total) > tolerance:
            raise ValueError('Unbalanced journal entry')
    for key in set(ledger) | set(result['ledger']):
        if not math.isclose(ledger.get(key, 0.), result['ledger'].get(key, 0.), abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Ledger differs from journal')
    initial = result['snapshots'][0]['metrics']['total_cash']
    for snapshot in result['snapshots']:
        firms, bank = snapshot['businesses'], snapshot['bank']
        if not math.isclose(bank['equity'], bank['cash'] + bank['loans'], abs_tol=tolerance):
            raise ValueError('Bank equity differs from assets')
        cash = bank['cash'] + snapshot['supplier']['cash'] + snapshot['customers']['cash'] + sum(f['cash'] for f in firms)
        if not math.isclose(cash, initial, abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Cash conservation violated')
        if not math.isclose(bank['loans'], sum(f['loan'] for f in firms), abs_tol=tolerance):
            raise ValueError('Loan assets and liabilities differ')
        for firm in firms:
            if not math.isclose(firm['equity'], firm['cash'] + firm['inventory_value'] - firm['loan'], abs_tol=tolerance):
                raise ValueError('Business equity differs from net assets')
            if firm['cash'] < -tolerance or firm['loan'] < -tolerance or firm['loan'] > firm['credit_limit'] + tolerance or not -tolerance <= firm['inventory'] <= firm['storage_capacity'] + tolerance:
                raise ValueError('Business balance or capacity constraint violated')
        if bank['cash'] < -tolerance or not -tolerance <= bank['loans'] <= bank['credit_limit'] + tolerance:
            raise ValueError('Bank balance or credit constraint violated')
    last = result['snapshots'][-1]
    expected = {'bank:cash': last['bank']['cash'], 'bank:loans': last['bank']['loans'],
                'supplier:cash': last['supplier']['cash'], 'customers:cash': last['customers']['cash']}
    for firm in last['businesses']:
        expected.update({firm['id'] + ':cash': firm['cash'], firm['id'] + ':loan': -firm['loan'],
                         firm['id'] + ':inventory': firm['inventory_value']})
        ident = firm['id']
        profit = -ledger.get(ident + ':sales_revenue', 0.) - ledger.get(ident + ':cost_of_goods', 0.) - ledger.get(ident + ':interest_expense', 0.)
        if not math.isclose(firm['profit'], profit, abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Business operating profit differs from ledger (debt relief excluded)')
    for key, value in expected.items():
        if not math.isclose(ledger.get(key, 0.), value, abs_tol=tolerance, rel_tol=1e-10):
            raise ValueError('Final state differs from journal: ' + key)
    final_firms = last['businesses']
    final_metrics = {'total_cash': sum(value for key, value in expected.items() if key.endswith(':cash')),
        'total_loans': last['bank']['loans'], 'total_inventory': sum(f['inventory'] for f in final_firms),
        'total_output': sum(f['output'] for f in final_firms), 'total_profit': sum(f['profit'] for f in final_firms),
        'total_interest': sum(f['interest'] for f in final_firms), 'total_energy_spend': sum(f['energy_spend'] for f in final_firms),
        'defaults': sum(f['defaulted'] for f in final_firms), 'stockouts': sum(e['kind'] == 'stockout' for e in result['events']),
        'bank_equity': last['bank']['equity'], 'business_cash': sum(f['cash'] for f in final_firms),
        'insolvent_businesses': sum(f['equity'] < -1e-9 for f in final_firms)}
    if set(result['metrics']) != set(final_metrics) or set(last['metrics']) != set(final_metrics):
        raise ValueError('Final metrics fields differ from accounting metrics')
    for key, value in final_metrics.items():
        for metrics in (last['metrics'], result['metrics']):
            if not math.isclose(metrics[key], value, abs_tol=tolerance, rel_tol=1e-10):
                raise ValueError('Final metrics inconsistent with state: ' + key)
    return {'balanced': True, 'cash_conserved': True, 'loan_assets_equal_liabilities': True, 'entries': len(result['journal'])}


def value_bond(face_value, coupon_rate, annual_yield, years, payments_per_year=2):
    """Fixed-coupon clean price at coupon date; nominal compounded yield."""
    face = _number(face_value, 'face_value')
    coupon = _number(coupon_rate, 'coupon_rate')
    years = _number(years, 'years')
    if face == 0 or years == 0 or isinstance(payments_per_year, bool) or not isinstance(payments_per_year, int) or not 1 <= payments_per_year <= 365:
        raise ValueError('Positive face, maturity and integer frequency required')
    y = _number(annual_yield, 'annual_yield', -payments_per_year)
    count = years * payments_per_year
    if y <= -payments_per_year or not count.is_integer() or count > 100000:
        raise ValueError('Maturity must have finite whole coupon periods and valid yield')
    try:
        flows = [(period / payments_per_year,
                  (face * coupon / payments_per_year + (face if period == int(count) else 0)) /
                  (1 + y / payments_per_year) ** period) for period in range(1, int(count) + 1)]
        price = sum(pv for _, pv in flows)
        duration = sum(time * pv for time, pv in flows) / price
        if not math.isfinite(price) or not math.isfinite(duration):
            raise ValueError('Bond calculation overflow')
    except (OverflowError, ZeroDivisionError) as exc:
        raise ValueError('Bond calculation outside finite numeric range') from exc
    return {'price': price, 'macaulay_duration_years': duration,
            'modified_duration': duration / (1 + y / payments_per_year),
            'dv01': price * duration / (1 + y / payments_per_year) * .0001}

